from __future__ import annotations

from dataclasses import dataclass
from typing import Literal

DecoderStrategy = Literal["D0", "D1", "D2", "D3"]
DecodeThreadType = Literal["AUTO", "FRAME"]
Precision = Literal["fp32", "fp16"]


@dataclass(frozen=True)
class PipelineConfig:
    decoder_strategy: DecoderStrategy = "D0"
    decode_thread_type: DecodeThreadType = "AUTO"
    decode_threads: int = 2
    prefetch_capacity: int = 64
    precision: Precision = "fp32"
    batch_size: int = 1

    def __post_init__(self) -> None:
        if self.decoder_strategy not in ("D0", "D1", "D2", "D3"):
            raise ValueError(f"invalid decoder_strategy: {self.decoder_strategy!r}")
        if self.decode_thread_type not in ("AUTO", "FRAME"):
            raise ValueError(f"invalid decode_thread_type: {self.decode_thread_type!r}")
        if self.decode_threads < 1:
            raise ValueError(f"decode_threads must be >= 1, got {self.decode_threads}")
        if self.prefetch_capacity < 1:
            raise ValueError(f"prefetch_capacity must be >= 1, got {self.prefetch_capacity}")
        if self.precision not in ("fp32", "fp16"):
            raise ValueError(f"invalid precision: {self.precision!r}")
        if self.batch_size < 1:
            raise ValueError(f"batch_size must be >= 1, got {self.batch_size}")

from __future__ import annotations

import io
import queue
import threading
import time
from dataclasses import dataclass
from fractions import Fraction
from typing import Callable, Iterable, Iterator

import numpy as np

from .config import PipelineConfig


@dataclass(frozen=True)
class DecodedFrame:
    image: np.ndarray
    timestamp: Fraction


def _as_fraction(value: object) -> Fraction:
    numerator = getattr(value, "numerator", None)
    denominator = getattr(value, "denominator", None)
    if numerator is None or denominator in (None, 0):
        raise ValueError(f"cannot convert {value!r} to a rational timestamp")
    return Fraction(int(numerator), int(denominator))


def frame_timestamp(frame: object, frame_index: int, fallback_rate: object) -> Fraction:
    pts = getattr(frame, "pts", None)
    time_base = getattr(frame, "time_base", None)
    if pts is not None and time_base is not None:
        return int(pts) * _as_fraction(time_base)
    rate = _as_fraction(fallback_rate)
    if rate <= 0:
        raise ValueError("video has no usable timestamps or frame rate")
    return Fraction(frame_index, 1) / rate


def rotate_bgr(image: np.ndarray, rotation: float | int | None) -> np.ndarray:
    if rotation is None:
        return np.ascontiguousarray(image)
    turns = round(float(rotation) / 90.0) % 4
    if turns:
        image = np.rot90(image, k=-turns, axes=(0, 1))
    return np.ascontiguousarray(image)


def decode_video(
    video_bytes: bytes,
    thread_type: str | None = None,
    thread_count: int | None = None,
) -> Iterator[DecodedFrame]:
    import av

    if not video_bytes:
        raise ValueError("empty video payload")
    with av.open(io.BytesIO(video_bytes), mode="r") as container:
        if not container.streams.video:
            raise ValueError("container has no video stream")
        stream = container.streams.video[0]
        if thread_type is not None and thread_count is not None and thread_count > 0:
            stream.codec_context.thread_type = thread_type
            stream.codec_context.thread_count = thread_count
        fallback_rate = stream.average_rate or stream.guessed_rate or stream.base_rate
        for frame_index, frame in enumerate(container.decode(stream)):
            timestamp = frame_timestamp(frame, frame_index, fallback_rate)
            image = frame.to_ndarray(format="bgr24")
            yield DecodedFrame(
                image=rotate_bgr(image, getattr(frame, "rotation", 0)),
                timestamp=timestamp,
            )


def decode_video_prefetched(
    video_bytes: bytes,
    thread_type: str | None = None,
    thread_count: int | None = None,
    capacity: int = 64,
) -> Iterator[DecodedFrame]:
    sentinel = object()
    q: queue.Queue[object] = queue.Queue(maxsize=capacity)
    exc_box: list[BaseException] = []
    stop_event = threading.Event()

    def producer() -> None:
        try:
            for frame in decode_video(
                video_bytes, thread_type=thread_type, thread_count=thread_count
            ):
                if stop_event.is_set():
                    break
                while not stop_event.is_set():
                    try:
                        q.put(frame, timeout=0.05)
                        break
                    except queue.Full:
                        continue
        except BaseException as exc:
            exc_box.append(exc)
        finally:
            while True:
                try:
                    q.put(sentinel, timeout=0.05)
                    break
                except queue.Full:
                    if stop_event.is_set():
                        break

    t = threading.Thread(target=producer, daemon=True)
    t.start()

    try:
        while True:
            item = q.get()
            if item is sentinel:
                break
            yield item  # type: ignore[misc]
        if exc_box:
            raise exc_box[0]
    finally:
        stop_event.set()
        while t.is_alive():
            try:
                drain = q.get_nowait()
                if drain is sentinel:
                    break
            except queue.Empty:
                time.sleep(0.005)
        t.join(timeout=2.0)


def get_decoder_for_config(
    config: PipelineConfig,
) -> Callable[[bytes], Iterable[DecodedFrame]]:
    if config.decoder_strategy == "D0":
        return decode_video
    elif config.decoder_strategy == "D1":
        return lambda vb: decode_video(
            vb,
            thread_type=config.decode_thread_type,
            thread_count=config.decode_threads,
        )
    elif config.decoder_strategy == "D2":
        return lambda vb: decode_video_prefetched(
            vb,
            capacity=config.prefetch_capacity,
        )
    elif config.decoder_strategy == "D3":
        return lambda vb: decode_video_prefetched(
            vb,
            thread_type=config.decode_thread_type,
            thread_count=config.decode_threads,
            capacity=config.prefetch_capacity,
        )
    else:
        raise ValueError(f"unknown decoder strategy: {config.decoder_strategy}")

from __future__ import annotations

from pathlib import Path
from typing import Sequence

import numpy as np
import torch
from ultralytics import YOLO

from .constants import TARGET_CLASS_IDS


class UltralyticsDetector:
    def __init__(
        self,
        model_path: Path,
        device: str = "auto",
        precision: str = "fp32",
    ) -> None:
        if not model_path.is_file():
            raise FileNotFoundError(
                f"model weights not found: {model_path}; run python prepare.py first"
            )
        self.device = "0" if device == "auto" and torch.cuda.is_available() else device
        if self.device == "auto":
            self.device = "cpu"
        if precision not in ("fp32", "fp16"):
            raise ValueError(f"invalid precision: {precision!r}")
        if precision == "fp16" and self.device == "cpu":
            raise RuntimeError("FP16 inference requires a CUDA device, but device is cpu")
        self.precision = precision
        self.half = precision == "fp16"
        self.model = YOLO(str(model_path))
        mismatches = {
            class_id: (expected, self.model.names.get(class_id))
            for class_id, expected in TARGET_CLASS_IDS.items()
            if self.model.names.get(class_id) != expected
        }
        if mismatches:
            raise RuntimeError(f"unexpected model class map: {mismatches}")

    def detect_many(self, images: Sequence[np.ndarray]) -> list[list[int]]:
        if not images:
            return []
        source: object = images[0] if len(images) == 1 else list(images)
        results = self.model.predict(
            source=source,
            imgsz=640,
            conf=0.4,
            iou=0.7,
            device=self.device,
            half=self.half,
            verbose=False,
        )
        detections: list[list[int]] = []
        for result in results:
            if result.boxes is None or result.boxes.cls is None:
                detections.append([])
            else:
                detections.append(
                    [int(value) for value in result.boxes.cls.detach().cpu().tolist()]
                )
        if len(detections) != len(images):
            raise RuntimeError(
                f"model returned {len(detections)} results for {len(images)} frames"
            )
        return detections

