import sys
from pathlib import Path
from typing import Dict, List, Tuple

from src.althia.distributed import WORKER_SHARD_RANGES, shard_filename

ROOT = Path(__file__).resolve().parents[1]

WORKER_METADATA: Dict[str, Dict[str, str]] = {
    "A": {
        "env_var": "KAGGLE_API",
        "username": "talhahassanulhaq",
        "dataset_slug": "althia-finevideo-shards-a",
        "title": "Althia FineVideo Shards Worker A",
    },
