        "dataset_slug": "althia-finevideo-shards-c",
        "title": "Althia FineVideo Shards Worker C",
    },
}


def load_env_tokens() -> Dict[str, str]:
    tokens = {}
    env_file = ROOT / ".env"
    if env_file.is_file():
        for line in env_file.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            k, v = line.split("=", 1)
            tokens[k.strip()] = v.strip().strip("\"'")
    return tokens


def stage_worker_files(
    worker_id: str,
    staging_base: Path,
    shards_dir: Path,
    reference_parquet: Path | None = None,
) -> Path:
    worker_info = WORKER_METADATA[worker_id]
    start_shard, end_shard = WORKER_SHARD_RANGES[worker_id]
    target_dir = staging_base / f"worker_{worker_id.lower()}"
    target_dir.mkdir(parents=True, exist_ok=True)

    metadata = {
        "title": worker_info["title"],
        "id": f"{worker_info['username']}/{worker_info['dataset_slug']}",
        "licenses": [{"name": "CC0-1.0"}],
    }
    meta_path = target_dir / "dataset-metadata.json"
    meta_path.write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")

    for s_idx in range(start_shard, end_shard + 1):
        fname = shard_filename(s_idx)
        src = shards_dir / fname
        if not src.is_file():
            raise FileNotFoundError(f"Missing required shard: {src}")
        dst = target_dir / fname
        if not dst.exists():
            try:
                os.link(src, dst)
            except OSError:
                shutil.copy2(src, dst)

    if reference_parquet and reference_parquet.is_file():
        ref_dst = target_dir / "reference.parquet"
        if not ref_dst.exists():
            try:
                os.link(reference_parquet, ref_dst)
            except OSError:
                shutil.copy2(reference_parquet, ref_dst)

    return target_dir


def upload_worker_dataset(worker_id: str, staging_dir: Path, token: str) -> None:
    from kaggle.api.kaggle_api_extended import KaggleApi

    worker_info = WORKER_METADATA[worker_id]
    dataset_ref = f"{worker_info['username']}/{worker_info['dataset_slug']}"

    os.environ["KAGGLE_API_TOKEN"] = token
    api = KaggleApi()
    api.authenticate()

    print(f"[{worker_id}] Checking if dataset {dataset_ref} exists...", flush=True)
    try:
        status = api.dataset_status(dataset_ref)
        print(f"[{worker_id}] Dataset {dataset_ref} already exists (status: {status}).", flush=True)
        return
    except Exception:
        print(f"[{worker_id}] Dataset {dataset_ref} does not exist yet. Creating...", flush=True)

    print(f"[{worker_id}] Uploading files from {staging_dir} to {dataset_ref}...", flush=True)
    response = api.dataset_create_new(
        str(staging_dir),
        public=False,
        quiet=False,
        dir_mode="skip",
    )
    print(f"[{worker_id}] Create dataset response: {response}", flush=True)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Stage and upload distributed datasets to Kaggle.")
    parser.add_argument("--workers", nargs="+", choices=["A", "B", "C"], default=["A", "B", "C"])
    parser.add_argument("--staging-base", type=Path, default=ROOT / "artifacts" / "staging")
    parser.add_argument("--shards-dir", type=Path, default=ROOT / "finevideo" / "data")
    parser.add_argument(
        "--reference-parquet",
        type=Path,
        default=ROOT / "artifacts" / "reference" / "input" / "reference.parquet",
    )
    parser.add_argument("--skip-upload", action="store_true", help="Stage files locally without uploading.")
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    tokens = [REMOVED]

    for worker_id in args.workers:
        print(f"=== Staging Worker {worker_id} ===", flush=True)
        staging_dir = stage_worker_files(
            worker_id=worker_id,
            staging_base=args.staging_base,
            shards_dir=args.shards_dir,
            reference_parquet=args.reference_parquet,
        )
        print(f"Staged {len(list(staging_dir.glob('*.parquet')))} Parquet files into {staging_dir}")

        if not args.skip_upload:
            env_var = WORKER_METADATA[worker_id]["env_var"]
            tok = tokens.get(env_var)
            if not tok:
                print(f"ERROR: Missing environment variable {env_var} in .env for Worker {worker_id}", file=sys.stderr)
                return 1
            upload_worker_dataset(worker_id, staging_dir, tok)

    return 0


if __name__ == "__main__":
    sys.exit(main())

